import React from 'react';
import 'bootstrap/dist/css/bootstrap.min.css';
import './Register.css';
import heartImg from '../../assets/heart.png';
import logo from '../../assets/Logo.png';
import { FaUser, FaEnvelope, FaLock, FaIdCard } from 'react-icons/fa';

const Register = () => {
  return (
    <div className="container-fluid vh-100 p-0">
      <div className="row g-0 h-100">

        {/* Left side */}
        <div
          className="col-md-4 d-none d-md-flex flex-column justify-content-center align-items-center text-center left-side"
        >
          <img src={logo} alt="logo" className="img-fluid mb-3 logo" />
          <h1 className="heart-title">Heart Diseases</h1>
        </div>

        {/* Right side */}
        <div className="col-md-8 d-flex justify-content-center align-items-center right-side">
          <div className="register-content">
            <h2>Register Page</h2>

            <div className="mb-3 input-group">
              <span className="input-group-text"><FaEnvelope /></span>
              <input type="email" className="form-control" placeholder="Email" />
            </div>

            <div className="mb-3 input-group">
              <span className="input-group-text"><FaIdCard /></span>
              <input type="text" className="form-control" placeholder="National ID" />
            </div>

            <div className="mb-3 input-group">
              <span className="input-group-text"><FaUser /></span>
              <input type="text" className="form-control" placeholder="Username" />
            </div>

            <div className="mb-3 input-group">
              <span className="input-group-text"><FaLock /></span>
              <input type="password" className="form-control" placeholder="Password" />
            </div>

            <button className="btn btn-gradient w-100 mb-3">Create Account</button>

            <div className="text-center login-link">
              Already have an account? <a href="/login">Login</a>
            </div>
          </div>
        </div>

      </div>
    </div>
  );
};

export default Register;
